import React, { useState } from 'react';
import { useTransactions } from '../../context/TransactionContext';
import { Link } from 'react-router-dom';
import './Transactions.css'; 

function Transactions() {
  const { transactions } = useTransactions();
  const [filter, setFilter] = useState('all'); // all, sent, received

  // Filter transactions
  const filteredTransactions = transactions.filter(transaction => {
    if (filter === 'sent') return transaction.type === 'send';
    if (filter === 'received') return transaction.type === 'receive';
    return true;
  });

  return (
    <div className="transactions-page">
      <header className="transactions-header">
        <h2>Transaction History</h2>
        <div className="filters">
          <button 
            className={filter === 'all' ? 'active' : ''} 
            onClick={() => setFilter('all')}
          >
            All
          </button>
          <button 
            className={filter === 'sent' ? 'active' : ''} 
            onClick={() => setFilter('sent')}
          >
            Sent
          </button>
          <button 
            className={filter === 'received' ? 'active' : ''} 
            onClick={() => setFilter('received')}
          >
            Received
          </button>
        </div>
      </header>

      <div className="transactions-list">
        {filteredTransactions.map(transaction => (
          <Link 
            to={`/transactions/${transaction.id}`} // Corrected URL string interpolation
            key={transaction.id} 
            className="transaction-item"
          >
            <div className="transaction-info">
              <p className="transaction-type">
                {transaction.type === 'send' ? 'Sent to' : 'Received from'}
              </p>
              <p className="transaction-party">
                {transaction.type === 'send' ? transaction.recipient : transaction.sender}
              </p>
              <p className="transaction-date">{transaction.date}</p>
            </div>
            <div className="transaction-amount">
              <p className={`amount ${transaction.type}`}> {/* Fixed template literal */}
                {transaction.type === 'send' ? '-' : '+'}${transaction.amount}
              </p>
              <p className={`status ${transaction.status}`}> {/* Fixed template literal */}
                {transaction.status}
              </p>
            </div>
          </Link>
        ))}
      </div>
    </div>
  );
}

export default Transactions;
